create table if not exists public.weekly_trend_battles(id uuid primary key default gen_random_uuid(),week_start date not null unique,category text not null,left_title text not null,right_title text not null,ends_at timestamptz not null,created_at timestamptz not null default now());
create table if not exists public.weekly_trend_battle_votes(id bigint generated always as identity primary key,battle_id uuid not null references public.weekly_trend_battles(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,choice text not null check(choice in('left','right')),created_at timestamptz not null default now(),unique(battle_id,user_id));
alter table public.weekly_trend_battles enable row level security;alter table public.weekly_trend_battle_votes enable row level security;
drop policy if exists "Weekly battles are public" on public.weekly_trend_battles;create policy "Weekly battles are public" on public.weekly_trend_battles for select using(true);
drop policy if exists "Weekly battle votes are public" on public.weekly_trend_battle_votes;create policy "Weekly battle votes are public" on public.weekly_trend_battle_votes for select using(true);
create or replace function public.get_or_create_weekly_trend_battle() returns setof public.weekly_trend_battles language plpgsql security definer set search_path=public as $$
declare v_week date:=date_trunc('week',now() at time zone 'UTC')::date;v_pair text[];v_idx integer;
begin v_idx:=mod(abs((extract(epoch from v_week::timestamp)::bigint/604800)::integer),6);v_pair:=case v_idx when 0 then array['Solo Leveling','Bleach','Anime'] when 1 then array['One Piece','Hunter x Hunter','Anime'] when 2 then array['Dune: Part Two','Godzilla Minus One','Film'] when 3 then array['The Glory','Moving','Drama'] when 4 then array['Frieren: Beyond Journey’s End','Vinland Saga','Anime'] else array['The Wild Robot','Spider-Man: Across the Spider-Verse','Animation'] end;insert into public.weekly_trend_battles(week_start,category,left_title,right_title,ends_at) values(v_week,v_pair[3],v_pair[1],v_pair[2],(v_week+7)::timestamp at time zone 'UTC') on conflict(week_start) do nothing;return query select * from public.weekly_trend_battles where week_start=v_week;end $$;
create or replace function public.vote_weekly_trend_battle(p_battle_id uuid,p_choice text) returns boolean language plpgsql security definer set search_path=public as $$
begin if auth.uid() is null then raise exception 'Sign in to vote.';end if;if p_choice not in('left','right') then raise exception 'Invalid vote.';end if;if not exists(select 1 from public.weekly_trend_battles where id=p_battle_id and ends_at>now()) then raise exception 'This weekly battle has closed.';end if;insert into public.weekly_trend_battle_votes(battle_id,user_id,choice) values(p_battle_id,auth.uid(),p_choice) on conflict(battle_id,user_id) do nothing;return found;end $$;
revoke all on function public.get_or_create_weekly_trend_battle() from public;grant execute on function public.get_or_create_weekly_trend_battle() to anon,authenticated;revoke all on function public.vote_weekly_trend_battle(uuid,text) from public,anon;grant execute on function public.vote_weekly_trend_battle(uuid,text) to authenticated;